fit = o[(o.placed_at>='2009-12-01')&(o.placed_at<='2010-11-30 23:59:59')].copy()
fit_end=fit.placed_at.max()
ref = pd.read_csv('reference/feature_sample.csv', dtype={'line_id':str})
