j = score.head(500)[['line_id','sku']].merge(ref[['line_id','f_sku_velocity']], on='line_id')
tgt = j.groupby('sku').f_sku_velocity.first()
skus=list(tgt.index)

# daily series per sku (trade days only)
dmap = {}
for sku in skus:
    s=fit[fit.sku==sku]
    dmap[sku]=s.groupby(s.placed_at.dt.normalize()).units.sum().sort_index()

# candidates as function of daily series
def mean_last(s, W):
    cutoff = fit_end.normalize()-pd.Timedelta(days=W)
    seg=s[s.index>=cutoff]
    return seg.mean() if len(seg) else 0.0
def sum_last(s, W):
    cutoff = fit_end.normalize()-pd.Timedelta(days=W)
    seg=s[s.index>cutoff]
    return seg.sum()/W
def ewm(s, span):
    return s.ewm(span=span).mean().iloc[-1]
def med(s): return s.median()
def mean(s): return s.mean()
def trimmed(s, q):
    lo,hi=s.quantile(q),s.quantile(1-q)
    return s[(s>=lo)&(s<=hi)].mean()
def mean_excl_max(s):
    return s.iloc[np.argsort(s.values)[:-1]].mean() if len(s)>1 else s.mean()

cands = {}
for W in [14,21,28,30,35,40,45,56,60,70,75,90,100,120]:
    cands['mean_last%d'%W]=lambda s,W=W: mean_last(s,W)
    cands['sum_last%d'%W]=lambda s,W=W: sum_last(s,W)
for sp in [7,14,21,30,45,60,90,120]:
    cands['ewm%d'%sp]=lambda s,sp=sp: ewm(s,sp)
cands['median']=med; cands['mean']=mean; cands['mean_excl_max']=mean_excl_max
for q in [0.05,0.1,0.2]:
    cands['trimmed%.2f'%q]=lambda s,q=q: trimmed(s,q)

results=[]
for name,f in cands.items():
    vals=np.array([f(dmap[k]) if len(dmap[k]) else 0.0 for k in skus])
    err=np.abs(vals-tgt.values)
    results.append((err.max(), err.mean(), name))
results.sort()
for r in results[:12]: print(r)
