import pandas as pd, numpy as np
import warnings; warnings.filterwarnings('ignore')
o = pd.read_csv('data/orders.csv.gz', parse_dates=['placed_at'], dtype={'order_id':str,'line_id':str})
o['sku']=o['sku'].astype(str)
fit = o[(o.placed_at>='2009-12-01')&(o.placed_at<='2010-11-30 23:59:59')].copy()
fit_end=fit.placed_at.max(); fit_start=fit.placed_at.min()
T=(fit_end-fit_start).total_seconds()/86400
ref = pd.read_csv('reference/feature_sample.csv', dtype={'line_id':str})
score = o[(o.placed_at>='2010-11-01')&(o.placed_at<='2010-11-30 23:59:59')].copy().sort_values('line_id')
j = score.head(500)[['line_id','sku']].merge(ref[['line_id','f_sku_velocity']], on='line_id')
tgt = j.groupby('sku').f_sku_velocity.first()
skus=list(tgt.index)

def lsq(t,c):
    t=np.asarray(t,float); c=np.asarray(c,float)
    tm=t.mean(); cm=c.mean()
    return ((t-tm)*(c-cm)).sum()/((t-tm)**2).sum()

def base_series(s, level):
    if level=='line':
        t=(s.placed_at-fit_start).dt.total_seconds()/86400
        u=s.units.astype(float)
    elif level=='order':
        per=s.groupby('order_id').agg(t=('placed_at','min'), u=('units','sum')).sort_values('t')
        t=(per.t-fit_start).dt.total_seconds()/86400; u=per.u.astype(float)
    else:
        d=s.groupby(s.placed_at.dt.normalize()).units.sum().sort_index()
        t=(d.index-fit_start).total_seconds()/86400; u=d.astype(float)
    return t.values, u.values

def variant(s, level, anchor):
    t,u = base_series(s, level)
    cu=np.cumsum(u)
    tt=list(t); cc=list(cu)
    if 'first0' in anchor:
        tt=[t[0]]+tt; cc=[0.0]+cc
    if 'origin' in anchor:
        tt=[0.0]+tt; cc=[0.0]+cc
    if 'end' in anchor:
        tt=tt+[T]; cc=cc+[cu[-1]]
    if len(tt)<2: return u.sum()/T
    return lsq(tt,cc)

for level in ['line','order','daily']:
    for anchor in ['','first0','origin','end','first0+end','origin+end']:
        vals=np.array([variant(fit[fit.sku==k], level, anchor) for k in skus])
        e=np.abs(vals-tgt.values)
        print('%-8s %-12s max %.6f mean %.6f'%(level,anchor,e.max(),e.mean()))
